WITH with_windows AS (SELECT id, order_id, quantity, unit_price, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity DESC, id ASC) AS event_seq, LEAD(quantity, 1) OVER (PARTITION BY product_id ORDER BY quantity ASC, id ASC) AS next_quantity FROM order_items) SELECT s.id, s.order_id, s.unit_price, s.event_seq, s.next_quantity, (SELECT SUM(x.amount) FROM payments x WHERE x.order_id = s.order_id) AS sum_payment_amount FROM with_windows s
